package nir.com.neonvegasslots;
import static org.junit.Assert.*;import android.graphics.*;import android.view.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=34,qualifiers="w320dp-h570dp-hdpi")public class MapButtonFeedbackTest{
 private MapView map(){MapView m=new MapView(RuntimeEnvironment.getApplication(),new SlotsView(RuntimeEnvironment.getApplication()));m.measure(View.MeasureSpec.makeMeasureSpec(420,1073741824),View.MeasureSpec.makeMeasureSpec(0,0));m.layout(0,0,420,m.getMeasuredHeight());return m;}
 private float scale(MapView m)throws Exception{Method f=MapView.class.getDeclaredMethod("stopScale",int.class);f.setAccessible(true);return (Float)f.invoke(m,0);}
 @GraphicsMode(GraphicsMode.Mode.NATIVE)@Test public void downScalesAndDimsMapStop()throws Exception{MapView m=map();m.onTouchEvent(MotionEvent.obtain(0,0,0,m.stopX(0),m.stopY(0),0));assertEquals(.95f,scale(m),.001);Bitmap b=Bitmap.createBitmap(420,700,Bitmap.Config.ARGB_8888);m.draw(new Canvas(b));try(FileOutputStream o=new FileOutputStream("/tmp/renders/neonvegasslots-map-pressed.png")){b.compress(Bitmap.CompressFormat.PNG,100,o);}}
 @Test public void cancelAndDragNeverSelectDestination()throws Exception{MapView m=map();m.onTouchEvent(MotionEvent.obtain(0,0,0,m.stopX(0),m.stopY(0),0));m.onTouchEvent(MotionEvent.obtain(0,10,2,m.stopX(0),m.stopY(0)+150,0));assertEquals(1,scale(m),.001);m.onTouchEvent(MotionEvent.obtain(0,20,3,m.stopX(0),m.stopY(0),0));assertEquals(1,scale(m),.001);}
 @Test public void releaseBouncesAndClickStillWorks()throws Exception{MapView m=map();final int[] n={0};m.setOnClickListener(v->n[0]++);m.onTouchEvent(MotionEvent.obtain(0,0,0,m.stopX(0),m.stopY(0),0));m.onTouchEvent(MotionEvent.obtain(0,10,1,m.stopX(0),m.stopY(0),0));assertEquals(1,n[0]);assertTrue(scale(m)<1);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(250));assertEquals(1,scale(m),.001);}
}
